# compute exact shape congruencies (D4) across components in test grid g
# g components comps as previously built, zero-based bounding box stored above

def shape_variants(cells):
    pts=list(cells); variants=[]
    for k in range(8):
        transformed=[]
        for r,c in pts:
            if k<4:
                # rotations
                x,y=r,c
                for _ in range(k): x,y=y,-x
            else:
                x,y=r,-c
                for _ in range(k-4): x,y=y,-x
            transformed.append((x,y))
        minx=min(x for x,y in transformed); miny=min(y for x,y in transformed)
        variants.append(tuple(sorted((x-minx,y-miny) for x,y in transformed)))
    return set(variants)
objs=[]
for col, ss in comps.items():
 for s in ss:
  objs.append((col,s,shape_variants(s)))
pairs=[]
for i,(c1,s1,v1) in enumerate(objs):
 for c2,s2,v2 in objs[i+1:]:
  if v1&v2:
   a=(min(r for r,c in s1),max(r for r,c in s1),min(c for r,c in s1),max(c for r,c in s1))
   b=(min(r for r,c in s2),max(r for r,c in s2),min(c for r,c in s2),max(c for r,c in s2))
   pairs.append((len(s1),c1,a,c2,b))
pairs

